import { NextResponse } from 'next/server'
import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db, setCurrentRlsServiceRole } from '@/lib/db'
import { PLATFORM_ADMIN_API_ROLES } from '@/lib/auth/rbac'
import { z } from 'zod'
import { logAuditEvent } from '@/lib/enterprise/auditTrail'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface AnnouncementRow {
  id: string
  title: string
  body: string
  target: string
  created_at: Date
}

export const dynamic = 'force-dynamic'
const announcementSchema = z.object({
  title: z.string().trim().min(1).max(200),
  body: z.string().trim().min(1).max(5000),
  target: z.enum(['all', 'free', 'pro', 'team', 'firm', 'enterprise']).default('all'),
}).strict()

/**
 * POST /api/admin/announcements
 *
 * Create a broadcast announcement visible to selected user groups.
 * Requires auth + super_admin or admin role.
 *
 * Body:
 *   title   (string, required)
 *   body    (string, required)
 *   target  ('all' | 'pro' | 'free' | 'enterprise', default 'all')
 */
export const POST = apiHandler(
  { auth: true, roles: PLATFORM_ADMIN_API_ROLES, schema: announcementSchema, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const payload = ctx.body as Record<string, unknown>
    const title = String(payload.title || '').trim()
    const body = String(payload.body || '').trim()
    const target = String(payload.target || 'all')

    if (!title || !body) {
      return NextResponse.json(
        { error: 'Title and body are required' },
        { status: 400 },
      )
    }

    const validTargets = ['all', 'pro', 'team', 'firm', 'free', 'enterprise']
    if (!validTargets.includes(target)) {
      return NextResponse.json(
        { error: 'Invalid target audience' },
        { status: 400 },
      )
    }

    const userId = ctx.userId

    setCurrentRlsServiceRole('platform_admin')
    const result = await db.transaction(async client => {
      const inserted = await client.query<AnnouncementRow>(
      `INSERT INTO announcements (title, body, target, created_by, created_at, published_at)
       VALUES ($1, $2, $3, $4, NOW(), NOW())
       RETURNING id, title, body, target, created_at`,
      [title, body, target, userId],
      )
      await logAuditEvent({ userId, action: 'announcement.published', resourceType: 'announcements',
        resourceId: inserted.rows[0].id, details: { title, target }, timestamp: new Date() }, client)
      return inserted
    })

    return apiSuccess(result.rows[0])
  },
)
